const helpText = {
  "pdd": "PDD: prompt-driven development for your coding agent.\n\nUsage: pdd <command> [options]\n\nOptions:\n  --version          Print the installed version.\n  --skill            Print the complete guide, skill and bundled references.\n\nCommands:\n  session            Open a coding agent with PDD guidance.\n  projects           List projects by name.\n  models             Show this machine's tool models and valid efforts.\n  workflow           List recipes, start runs and review saved work.\n  setup              Set up this machine, or check and repair it.\n  join               Join an existing fleet.\n  fleet              Show and manage your machines and phones.\n  accounts           Add accounts once and use them on your machines.\n  agents             List agents on your machines.\n  agent              Read, answer, resume or stop one agent.\n  open               Open an agent's terminal.\n  status             Show Needs you, agents and runs.\n  settings           Show or change your settings.\n  phone              Pair an optional phone.\n  link               Show or control this machine's Link service.\n  update             Show or change PDD updates.\n  doctor             Check this machine and show repair steps.\n  completion         Print Bash or Zsh completion.\n  help [command]     Show help for a command.\n\nRun pdd <command> --help for options.\nWorkflow runs can push branches and create real pull requests.\nPDD never merges a pull request.\n\n  -h, --help  Show this help.",
  "pdd help": "Usage: pdd help [command [subcommand]]\n\nShow command help. This command changes nothing.\n\n  -h, --help  Show this help.",
  "pdd --version": "Usage: pdd --version\n\nPrint only the installed package version and a newline.",
  "pdd --skill": "Usage: pdd --skill\n\nPrint the complete Prompting guide first, then the skill and all bundled references.\n\nRead the complete guide before you write a Story.\nMissing guidance returns an error before a native agent starts.",
  "pdd completion": "Usage: pdd completion bash|zsh\n\nPrint completion code to standard output. Shell files do not change.\n\nWorkflow names come from local workflow list --json.\nFish completion is not supplied.\n\n  -h, --help  Show this help.",
  "pdd setup": "Usage: pdd setup [--no-phone]\n\nSet up a first machine. Run again to check and repair this installation.\n\nOptions:\n  --no-phone  Finish without offering phone pairing.\n\nAsk which tools you use: Codex, Claude or both.\nShow detected tools and offer their documented installers when missing.\nAsk before required PATH edits, selected Herdr hooks and Linux linger.\nInspect old LaunchAgents, units and pocket helpers later with doctor --cleanup.\nRequire the shim first in each installed supported shell (zsh, bash, fish)\nand in a Herdr pane.\nShow the command that wins and one repair step when it does not.\nSave a checkpoint after each phase. Rerun pdd setup to continue safely.\nUse gh auth login (install gh if needed) with repo, read:org and workflow.\nCheck existing gh identity and scopes before reuse; ask before sharing.\nShow organization restrictions and the approval path.\nAsk for each tool: You signed in as X — is this right?\nConfirm each tool account before sending its PDD sign-in to the keeper.\nSet one account or Auto once per machine per tool in Settings.\nNew agents and workflows use that setting without an account question.\nIf this GitHub account already has a fleet, offer pdd join.\nPrint Member ready and Provider ready separately.\nThe phone is optional. Your own tool sign-ins stay in place.\nIf all members are lost, GitHub proof permits delete-all only.\nCreate a fresh fleet only after deletion, or an existing member\nauthorizes a replacement with a signed operation and person check.\n\n  -h, --help  Show this help.",
  "pdd join": "Usage: pdd join\n\nShow a join code on the new machine and wait for approval.\n\nOn an existing member: pdd fleet approve CODE.\nThe new machine shows the three words; type them on the approving member.\nA join code lasts 10 minutes. Expiry or rejection needs a fresh pdd join.\nThe sponsor carries the tenant identity. No GitHub sign-in on this machine.\nShow the shared GitHub, Claude and API-key copies before approval.\nThe phone can approve and deliver sealed copies by itself.\nCodex access copies come from the keeper.\nPrint Member ready and Provider ready separately.\n\n  -h, --help  Show this help.",
  "pdd fleet": "Usage: pdd fleet <command>\n\nShow and manage your fleet.\n\nCommands: status, approve, remove, admissions, tag, rename, set-endpoints.\nMembership changes need Touch ID, typed words or approval on your phone.\n\n  -h, --help  Show this help.",
  "pdd fleet status": "Usage: pdd fleet status\n\nShow machine health, last seen time, tags, accounts and update state.\n\nShow Link, Herdr, free disk, versions, relay and keeper reachability.\nKeep stale data visible with its age.\nShow Member ready and Provider ready separately for a joining machine.\n\n  -h, --help  Show this help.",
  "pdd fleet approve": "Usage: pdd fleet approve CODE\n\nApprove the machine that shows this join code.\n\nCheck its name and key details.\nUse Touch ID, or type the three words shown on the new machine.\nThis screen does not reveal those words.\nAn expired or rejected request needs a new pdd join.\n\n  -h, --help  Show this help.",
  "pdd fleet remove": "Usage: pdd fleet remove MEMBER\n\nRemove a machine or phone after a person check.\n\nRemoval is permanent for this member key. Review its admissions next.\nReport local removal and keeper receipt separately.\nRemoval stops new delivery. It does not revoke copies already held.\nRotate the GitHub token and API keys. Replace Claude tokens.\nOld Claude tokens may remain valid. Codex copies can last up to 10 days.\n\n  -h, --help  Show this help.",
  "pdd fleet admissions": "Usage: pdd fleet admissions MEMBER\n\nShow machines and phones admitted by this member.\n\nShow pending or quarantined admissions and their reasons.\nUse pdd fleet approve CODE to approve a fresh request.\nUse pdd fleet remove MEMBER to remove an admitted member.\n\n  -h, --help  Show this help.",
  "pdd fleet tag": "Usage: pdd fleet tag MACHINE always-on|laptop\n\nSet a machine tag used for run placement.\n\nalways-on means this is your machine and you keep it awake.\nNo machine needs this tag. Without it, automatic runs stay where started.\nThe laptop tag reduces its placement score.\n\n  -h, --help  Show this help.",
  "pdd fleet set-endpoints": "Usage: pdd fleet set-endpoints [--relay URL] [--keeper URL] [--app URL]\n\nPublish service addresses as a signed fleet setting.\n\nOptions:\n  --relay URL   Set the relay HTTPS origin.\n  --keeper URL  Set the keeper HTTPS base URL.\n  --app URL     Set the phone app HTTPS origin.\n\nAt least one option is required.\nRelay and keeper moves do not restart agents.\nA new app origin needs a new Home Screen install and phone pairing.\n\n  -h, --help  Show this help.",
  "pdd accounts": "Usage: pdd accounts [command]\n\nShow your accounts, room, renewal times and machines allowed to use them.\n\nCommands: add, remove, resign, delete-all, mode, when-out, policy, allow,\n          quota-decide, migrate-sessions, rotate.\nUnknown usage is shown as unknown. It is never shown as full or empty.\nPDD never spends a usage-limit reset credit.\nPDD never falls back to API-key billing by itself.\n\n  -h, --help  Show this help.",
  "pdd accounts add": "Usage: pdd accounts add codex|claude|anthropic-key NAME [options]\n\nAdd an account once for use on your approved machines.\n\nOptions:\n  --from-pool  Codex only. Read a team account from the pool; team access required.\n  --replace    Claude or anthropic-key only. Replace the stored token or key.\n\nCodex uses a fresh scratch-home sign-in for the keeper.\nYour own Codex login stays in place. No refresh token goes to another machine.\nClaude uses an official one-year setup-token and needs an eligible plan.\nEnter API keys in the hidden prompt. Never put a key in a command line.\nShow and confirm the account identity before storing it.\nAsk: You signed in as X — is this right?\nFor Codex also show masked email, plan and the last four account-id characters.\nOffer Back and Retry. Cancel removes the scratch home and adds no account.\nReplacing a Claude token does not prove that the old token was revoked.\n\n  -h, --help  Show this help.",
  "pdd accounts remove": "Usage: pdd accounts remove ACCOUNT\n\nDelete the account from PDD and stop new copy delivery.\n\nConfirm the account before deletion.\nShow keeper deletion separately from machine cleanup.\nOffline copies can remain until expiry. Your own tool login stays in place.\nPDD does not call provider-wide logout during this operation.\n\n  -h, --help  Show this help.",
  "pdd accounts resign": "Usage: pdd accounts resign ACCOUNT\n\nCreate a fresh PDD Codex sign-in for a kept account.\n\nUse a scratch home. Show and confirm the identity.\nFor a team pool account, ask the pool owner. PDD never refreshes it.\nA new sign-in does not prove the old copies were revoked.\n\n  -h, --help  Show this help.",
  "pdd accounts delete-all": "Usage: pdd accounts delete-all\n\nDelete every sign-in and copy stored for you by PDD.\n\nType DELETE to confirm.\nDelete keeper homes, copies, usage and account audit entries at once.\nClear online machine caches. Offline machines clear them when they return.\nShow a pending result if the keeper or a machine has not confirmed deletion.\nCopies already on a machine or phone may work until they expire or are revoked.\nYour own tool logins and chats stay. The fleet remains paired.\nPDD does not call provider-wide logout.\n\n  -h, --help  Show this help.",
  "pdd accounts mode": "Usage: pdd accounts mode [--machine MACHINE] TOOL [auto|ACCOUNT]\n\nShow or change the machine account setting for one tool.\n\nOptions:\n  --machine MACHINE  Select a machine (default: this machine).\n  TOOL               codex or claude; the Settings entry to change.\n\nSet one account or Auto in Settings once per machine per tool.\nEvery managed agent and workflow on that machine uses this setting.\nAuto stays within the selected tool. Cross-tool permission is separate.\nAuto prefers earliest weekly renewal, then available room.\nUnknown Claude usage sorts last; a successful request establishes eligibility.\nThe whole machine selects the next Auto account. Each agent moves when its\ncurrent step ends. Show the machine target and each pending transition.\nA fixed account pauses agents when full: Use Auto / Pick another account /\nWait until the renewal. The first two choices change this machine/tool setting.\nA fixed account must match the tool and be allowed on the machine.\nTwo machines may share one account; usage is shared.\nNo user, agent or run account override is accepted.\n\n  -h, --help  Show this help.",
  "pdd accounts when-out": "Usage: pdd accounts when-out [--machine MACHINE] TOOL [ask|continue|wait]\n\nShow or set cross-tool behavior for this machine and source tool.\n\nOptions:\n  --machine MACHINE  Select a machine (default: this machine).\n  TOOL               codex or claude; the source tool.\n\nask (default): ask before a new chat in the other tool.\ncontinue: allow that new chat. Both tools must be configured.\nwait: retain the work and retry after renewal.\nAuto does not itself permit crossing tools.\nA fixed-account pause first offers Use Auto / Pick another account /\nWait until the renewal; a cross-tool setting does not bypass that question.\nUnknown renewal is shown as renewal time unknown.\nRetry failed or inconclusive observations after 5, 15 and 60 minutes,\nthen hourly. WAIT ends only after a fresh check or successful request shows room.\nA retry never sends the continuation message twice.\nA permitted handoff uses the destination tool's machine account setting.\n\n  -h, --help  Show this help.",
  "pdd accounts quota-decide": "Usage: pdd accounts quota-decide QUESTION_ID --decision continue|wait --rev N\n\nAnswer one saved controller cross-tool quota question.\n\nOptions:\n  --decision continue|wait  Continue in the other tool, or wait for quota.\n  --rev N                   Expected current quota-wait revision.\n\nUse the question id and revision shown in the run's cross-tool quota status.\nFixed-account Use Auto / Pick another account changes machine/tool Settings,\nnot a run account override. Wait until the renewal keeps that fixed account.\nRefuse a question or revision that no longer matches the current wait.\nA stale answer changes nothing. Inspect the run again before answering.\nThis command records the decision. It never sends a continuation itself.\nThe quota flow sends once under its saved attempt and turn key.\nThis is a quota answer, not workflow approve or skip.\n\n  -h, --help  Show this help.",
  "pdd accounts migrate-sessions": "Usage: pdd accounts migrate-sessions\n\nPreview and copy old PDD Codex session logs into the shared sessions home.\n\nShow source folders and conflicts before asking to copy.\nCopy session history only. Keep sources and distinct same-name files.\nNever read, copy or change auth.json. Never sign an account out.\n\n  -h, --help  Show this help.",
  "pdd accounts rotate": "Usage: pdd accounts rotate github\n\nReplace the shared GitHub token through a new gh device sign-in.\n\nRun on any approved member.\nConfirm the GitHub identity and scopes before sharing.\nShow old-grant revocation separately from the new token delivery.\nA failed revocation needs a manual GitHub settings step.\n\n  -h, --help  Show this help.",
  "pdd projects": "Usage: pdd projects [--on MACHINE]\n\nList projects by name, source and availability.\n\nOptions:\n  --on MACHINE  Read projects on this online machine; default: this machine.\n\nRead the same catalog as Projects and New agent; names come first.\nNew agent preselects the last successfully used project when still available.\nFind projects from past Codex/Claude chats, Herdr, runs and usual folders.\nProjects offers GitHub repos, Browse folders and New project actions.\nList GitHub repos as local or not cloned; list sources and availability.\nProjects actions explicitly clone to ~/pdd/<repo> after confirmation.\nChange the base folder with pdd settings projects.base VALUE.\nThe Projects Browse action uses folder choices, without typing a path.\nShow matching names with machine and repo details when names repeat.\nOffline or missing discovery sources keep other results and show their status.\nThis command only lists. It asks no questions, clones nothing and starts no agent.\nNo matches: No projects found. Use pdd session --project NAME to start.\nPhone tabs: Home, Agents, Runs, Projects, Machines.\nAccounts live in Settings; the Home usage bar opens that view.\n\n  -h, --help  Show this help.",
  "pdd models": "Usage: pdd models [--on MACHINE] --agent codex|claude\n\nShow visible native models and each model’s accepted efforts.\n\nOptions:\n  --on MACHINE         Read the selected online machine; default: this machine.\n  --agent codex|claude  Select the installed native tool.\n\nRead Codex model/list and supported efforts; exclude hidden models.\nFor Claude, read its own model names and tested model/plan effort support.\nShow the source machine and list status. No universal model or effort list.\nAn unavailable source returns a reason and retry step, never guessed choices.\nThis command changes no defaults and starts no agent.\n\n  -h, --help  Show this help.",
  "pdd session": "Usage: pdd session [--project NAME] [--agent codex|claude] [--on MACHINE] [--model MODEL] [--effort EFFORT] [--] [REQUEST ...]\n\nOpen a coding agent in a named project with the complete PDD guide.\n\nOptions:\n  --project NAME       Match a project name or part of its name.\n  --agent codex|claude  Select the native tool (default: codex).\n  --on MACHINE         Start on one of your online machines.\n  --model MODEL        Select a visible model from that machine's tool list.\n  --effort EFFORT      Select an effort accepted by that model and plan.\n  --                    End PDD options; remaining words form the request.\n\nUse pdd projects for the shared named list.\nWithout --project, preserve the current working folder. New agent preselects\nthe last successfully used project from this same catalog.\nMore than one name match returns exit 2 with candidates; never silently pick one.\nResolve the project on the target machine. Missing or uncloned: exit 1\nwith a Projects next step; no implicit clone. Projects offers explicit GitHub\nclone, Browse folders and New project actions. Browse uses folder choices.\nShow target machine, project, tool, model and effort before starting.\nAsk before cloning. Default base: ~/pdd; change projects.base in Settings.\nNever copy a dirty local worktree silently.\nUse per-tool model and effort defaults from the target machine's Settings.\nIf unset, use the installed CLI's observed defaults; if unknown, stop.\nA model override keeps the Settings effort if valid, else uses that model's\nobserved default effort. No effort control means omit the native effort flag.\nCodex uses model/list with hidden models removed and per-model efforts.\nClaude uses that machine's model names and tested effort support for its plan.\nAn invalid pair fails before launch. An unavailable list needs a retry;\nnever offer a hardcoded fallback. Refresh choices when machine, tool, model\nor account plan changes. Preserve work if a saved pair is no longer valid.\nThe account comes from Settings for this machine and tool. No launch picker.\nPDD work starts from user stories, Stories, prompts and cases. Finish the\nspecification for each part before generating its code.\nPDD-managed means pdd session, workflow stages, phone starts and restores.\nOrdinary typed codex and claude pass through unchanged by default.\nPDD_SHIM=off codex (or claude) is the stock-tool escape hatch.\nCheck Provider ready before starting; show the reason and one repair command.\nNo arbitrary native flag passthrough. Sessions run with full access.\nAlpha alone uses an existing local tool login.\nMissing executable: 127. Native signal: 128 plus its number.\n\n  -h, --help  Show this help.",
  "pdd workflow": "Usage: pdd workflow <command>\n\nFollow a recipe in one conversation, or manage a saved issue run.\n\nRecipes: feature, bug, small-change.\nRun commands: list, run, resume, attach, drive, decide, status, adopt, clean, upgrade.\nA recipe shortcut uses one conversation.\nAn issue run uses fresh stages and can push branches and create pull requests.\nPDD never merges.\n\n  -h, --help  Show this help.",
  "pdd workflow feature": "Usage: pdd workflow feature [--agent codex|claude] [--] [REQUEST ...]\n\nOpen one normal conversation with this bundled recipe.\n\nOptions:\n  --agent codex|claude  Select the native tool (default: codex).\n  --                    End PDD options.\n\nNo saved issue run is created. No automatic PR publication.\nUse the machine/tool account setting and its model/effort defaults.\nFinish Stories, prompts and cases before building each part.\nNo arbitrary native flags or recipe paths are accepted.\n\n  -h, --help  Show this help.",
  "pdd workflow bug": "Usage: pdd workflow bug [--agent codex|claude] [--] [REQUEST ...]\n\nOpen one normal conversation with this bundled recipe.\n\nOptions:\n  --agent codex|claude  Select the native tool (default: codex).\n  --                    End PDD options.\n\nNo saved issue run is created. No automatic PR publication.\nUse the machine/tool account setting and its model/effort defaults.\nFinish Stories, prompts and cases before building each part.\nNo arbitrary native flags or recipe paths are accepted.\n\n  -h, --help  Show this help.",
  "pdd workflow small-change": "Usage: pdd workflow small-change [--agent codex|claude] [--] [REQUEST ...]\n\nOpen one normal conversation with this bundled recipe.\n\nOptions:\n  --agent codex|claude  Select the native tool (default: codex).\n  --                    End PDD options.\n\nNo saved issue run is created. No automatic PR publication.\nUse the machine/tool account setting and its model/effort defaults.\nFinish Stories, prompts and cases before building each part.\nNo arbitrary native flags or recipe paths are accepted.\n\n  -h, --help  Show this help.",
  "pdd workflow list": "Usage: pdd workflow list [--json]\n\nList validated local and bundled workflow definitions.\n\nOptions:\n  --json  Print {workflows: [{name, source}], default: null}.\n\nA valid project definition overrides the bundled definition of that name.\nAn invalid override is an error. This command starts no agent.\n\n  -h, --help  Show this help.",
  "pdd workflow run": "Usage: pdd workflow run NAME ISSUE [--agent codex|claude] [--on auto|MACHINE] [--project NAME] [--model MODEL] [--effort EFFORT]\n\nStart a saved issue run in its own worktree and Herdr tab.\n\nOptions:\n  --agent codex|claude  Select the tool (default: codex).\n  --on auto|MACHINE     Select automatic placement or a machine.\n  --project NAME       Match a project name on the selected machine.\n  --model MODEL        Override its tool model default for this run.\n  --effort EFFORT      Override its model effort default for this run.\n\nNAME starts with a lowercase letter and uses lowercase letters, digits\nand single hyphens between nonempty groups. Maximum: 64 characters.\nISSUE is a positive number, OWNER/REPO#NUMBER or an HTTPS GitHub issue URL.\nA number is resolved in the current repository. Pull request URLs are invalid.\nWithout --on, run locally. With auto and no always-on tag, stay here.\nThe selected machine must still be online and eligible; otherwise show why.\nShow the saved run id, machine, worktree and controller state.\nThe controller lives in a Herdr pane. Closing this terminal does not stop it.\nA launch with no process proof is uncertain. Do not start a second run.\nInputs and runtime are saved for this run. Updates keep its version.\nUse the machine/tool account setting for all stages. No run account choice.\nUse that tool's model and effort defaults, or the valid start-time overrides.\nValidate model and effort from the selected machine before any stage starts.\nA model override keeps a supported Settings effort, else the model's observed\ndefault effort. With no effort control, omit that flag. Unknown defaults stop.\nResolve --project by name as for session; without it, use the current project.\nComplete user stories, Stories, prompts and cases before building each part.\nBefore a managed stage starts, check Provider ready and print an actionable\nrepair step if it is unavailable. Do not expose only credential-helper exit 3.\nThis command can push branches and create real pull requests.\n\n  -h, --help  Show this help.",
  "pdd workflow resume": "Usage: pdd workflow resume RUN_ID [--decision approve|skip] [--id DECISION_ID] [--rev N] [--expect-stage STAGE --expect-seq N]\n\nReconcile a saved run using its original inputs and worktree.\n\nOptions:\n  --decision approve|skip  Record a human choice. Skip requires an optional stage.\n  --id DECISION_ID          Reuse this decision id when retrying.\n  --rev N                   Require this human-wait revision; needs --id and --decision.\n  --expect-stage STAGE      Require this stage; use with --expect-seq and --id.\n  --expect-seq N            Require this journal sequence; use with --expect-stage.\n\nWithout a decision, inspect and reconcile; do not start the next stage.\nUse decide --rev for a current Fleet approval.\nMerge waits observe the saved pull request. They never merge it.\nUnknown outcomes never permit a blind restart or resend.\nExit: 0 completed, 2 waiting, 1 failed or needs recovery.\n\n  -h, --help  Show this help.",
  "pdd workflow attach": "Usage: pdd workflow attach RUN_ID\n\nAttach to the actual active stage terminal of a saved run.\n\nDo not start a new conversation.\nFor an archived stage, print saved information and the next step.\nNo agent override or native flag passthrough.\n\n  -h, --help  Show this help.",
  "pdd workflow drive": "Usage: pdd workflow drive RUN_ID [--decision approve|skip --id ACTION_ID --rev N] [--launch-id LAUNCH_ID]\n\nRun the saved controller using its recorded runtime.\n\nOptions:\n  --decision approve|skip  Carry a current human decision.\n  --id ACTION_ID           Decision UUID; use with --decision.\n  --rev N                  Require this human-wait revision.\n  --expect-stage STAGE     Legacy stage guard; needs --expect-seq.\n  --expect-seq N           Legacy journal guard; needs --expect-stage.\n  --launch-id LAUNCH_ID    Internal launch UUID for process proof, not approval.\n\nInternal recovery and explicit local use. One controller per run.\nRefuse a live controller or an unadopted old run.\nA waiting-person run needs its current revision and explicit decision.\nUse the journal to reconcile uncertain actions before doing work.\n\n  -h, --help  Show this help.",
  "pdd workflow decide": "Usage: pdd workflow decide RUN_ID --decision approve|skip --rev N --id ACTION_ID [--json]\n\nApply a decision only to the revision you reviewed.\n\nOptions:\n  --decision approve|skip  Approve the current proposal, or skip an optional stage.\n  --rev N                  Expected current human-wait revision.\n  --id ACTION_ID           Decision UUID. Reuse it for the same decision retry.\n  --json                   Print one versioned result object.\n\nA stale revision is refused before effects. Inspect the run and review again.\nA recorded decision retry returns its saved result without repeating work.\nNo process proof after launch means uncertain. Never type the line again blindly.\nCompatibility form: replace --rev N with --expect-stage STAGE --expect-seq N.\nIf both expectation forms are supplied, both must match.\nA legacy pair must name the exact current human-wait sequence.\nExit: 0 recorded or proven started, 1 refused/failed/uncertain, 2 bad arguments.\n\n  -h, --help  Show this help.",
  "pdd workflow status": "Usage: pdd workflow status [RUN_ID] [--json]\n\nShow saved runs, or the detail and revision of one run.\n\nOptions:\n  --json  Print the status object with v: 1.\n\nShow machine, project, step, version, tool, model, effort, current machine account, WAIT and Needs you.\nStatus is a view of the journal. This command never advances a run.\n\n  -h, --help  Show this help.",
  "pdd workflow adopt": "Usage: pdd workflow adopt RUN_ID\n\nReview an old run before enabling automatic recovery.\n\nShow the saved issue, worktree, stage, runtime and unresolved effects.\nAsk before recording adoption. No unknown action is repeated.\n\n  -h, --help  Show this help.",
  "pdd workflow clean": "Usage: pdd workflow clean [--dry-run]\n\nRemove only old worktrees whose work is retained elsewhere.\n\nOptions:\n  --dry-run  Show removal candidates and retention reasons; remove nothing.\n\nEligibility starts seven days after the pull request closed.\nKeep unfinished runs, WAIT, live claims, changed or untracked files,\nand any commit without a retained copy. Keep the journal and artifacts.\nA closed, unmerged pull request with unique work shows Needs you\nand asks for a retention choice. Never remove it automatically.\nShow the reason for every retained worktree. Never delete unpushed work.\n\n  -h, --help  Show this help.",
  "pdd workflow upgrade": "Usage: pdd workflow upgrade RUN_ID\n\nMove a saved run to the current PDD runtime at a safe boundary.\n\nShow old and new versions. Ask before recording the transition.\nKeep the original inputs, worktree, attempt and uncertain-effect history.\nRequire a stopped stage boundary and the current reviewed wait revision.\nNo live turn or unresolved effect may move.\nSave old/new runtime identities and an upgrade intent before changing the record.\nThe controller records the result. Recovery uses the durably committed side.\nA blocked version needs this review.\n\n  -h, --help  Show this help.",
  "pdd status": "Usage: pdd status\n\nShow Needs you first, then a short view of agents and runs.\n\nInclude account repairs, quota questions, joins and rollback notices.\nOffline machines keep their last state and age.\nShow each run revision with its review action.\n\n  -h, --help  Show this help.",
  "pdd agents": "Usage: pdd agents [--search TEXT]\n\nList agents by machine and project.\n\nOptions:\n  --search TEXT  Search names and visible agent details.\n\nGroup by machine and project; no Project filter.\nShow tool, model, effort, current machine account, status, age, pending step transition and replacement chat.\nCopy the full agent id from this list for pdd agent or pdd open.\n\n  -h, --help  Show this help.",
  "pdd open": "Usage: pdd open AGENT\n\nOpen the saved agent terminal on its machine.\n\nResolve the actual current pane. Do not start a duplicate session.\nFor a remote machine, use an available SSH route with your permission.\nIf no route is configured, show the machine and the local open command.\n\n  -h, --help  Show this help.",
  "pdd agent": "Usage: pdd agent <command> AGENT\n\nRead or control one agent.\n\nCommands: show, send, keys, resume, stop, dismiss.\nUse the full agent id from pdd agents.\nAccount changes belong to Settings for the machine and tool; all its agents use them.\n\n  -h, --help  Show this help.",
  "pdd agent show": "Usage: pdd agent show AGENT [--terminal]\n\nShow recent chat or the visible terminal screen.\n\nOptions:\n  --terminal  Show the current screen snapshot instead of recent chat.\n\nCached or stale content includes its age. This command sends no input.\n\n  -h, --help  Show this help.",
  "pdd agent send": "Usage: pdd agent send AGENT TEXT --id ACTION_ID\n\nSend a message once to a working or idle agent.\n\nOptions:\n  --id ACTION_ID  Action UUID. Reuse it for the same retry.\n\nA blocked agent needs pdd agent keys.\nIf delivery is uncertain, inspect the chat before sending again.\nThis command does not answer a workflow quota handoff question.\n\n  -h, --help  Show this help.",
  "pdd agent keys": "Usage: pdd agent keys AGENT KEY [KEY ...] --id ACTION_ID\n\nAnswer a native question or send allowed terminal keys once.\n\nOptions:\n  --id ACTION_ID  Action UUID. Reuse it for the same retry.\n\nKeys: enter, esc, arrows (up/down/left/right), tab, space, backspace,\nctrl+c, 0 through 9, y, n. Unknown outcomes never repeat keys.\n\n  -h, --help  Show this help.",
  "pdd agent resume": "Usage: pdd agent resume AGENT --id ACTION_ID\n\nResume a stopped session from its saved history.\n\nOptions:\n  --id ACTION_ID  Action UUID. Reuse it for the same retry.\n\nIf already running, show the existing session.\nUse the current replacement chat if the old one was retired.\nRefuse when the history is missing; show the machine and next step.\n\n  -h, --help  Show this help.",
  "pdd agent stop": "Usage: pdd agent stop AGENT --how interrupt|exit|close --id ACTION_ID\n\nInterrupt, exit or close only this agent pane.\n\nOptions:\n  --how interrupt|exit|close  Choose the effect. Close asks for confirmation.\n  --id ACTION_ID             Action UUID. Reuse it for the same retry.\n\nDo not close the controller or another agent pane.\n\n  -h, --help  Show this help.",
  "pdd agent dismiss": "Usage: pdd agent dismiss AGENT\n\nHide a stopped agent from the active list.\n\nKeep its native history. A working agent cannot be dismissed.\n\n  -h, --help  Show this help.",
  "pdd settings": "Usage: pdd settings [KEY VALUE] [--machine MACHINE] [--tool codex|claude]\n\nShow Settings, including accounts, or change one setting.\n\nOptions:\n  --machine MACHINE  Select a machine; default: this machine.\n  --tool codex|claude  Required for model and effort defaults.\n\nKeys:\n  model                   A visible native model; requires --tool.\n  effort                  Valid for the tool's selected model; requires --tool.\n  projects.base           Clone base folder (default: ~/pdd).\n  auto-switch-my-sessions  on|off (default: off)\n  auto.order              earliest-reset|most-remaining (default: earliest-reset)\n  alerts                  on|off\n  alert-text              show|hide\n\nModel and effort defaults belong to the selected machine/tool. Query its CLI;\nnever persist a hidden model or unsupported model/effort pair.\nA changed model uses its observed default effort if the old effort is invalid.\nModels without effort control expose no effort picker or native effort flag.\nAgents use these defaults; workflows do too unless overridden at run start.\nUse accounts mode TOOL for this machine's one account or Auto.\nUse accounts when-out TOOL for cross-tool permission (default: ask).\nAccount management lives in Settings. The Home usage bar opens this view.\nUse update --mode and update --channel for update choices.\nUse fleet set-endpoints for service addresses.\nChanges are signed settings. Alert choices apply to the current member.\n\n  -h, --help  Show this help.",
  "pdd phone": "Usage: pdd phone [--relay URL] [--name NAME] [--codex PATH] [--claude PATH] [--no-integrations]\n\nPair an optional phone. Complete machine setup first.\n\nOptions:\n  --relay URL        Relay address: HTTPS, or HTTP on loopback only.\n  --name NAME        Set this machine name (1 to 60 characters).\n  --codex PATH       Select the installed Codex binary.\n  --claude PATH      Select the installed Claude binary.\n  --no-integrations  Skip Herdr hook installation.\n\nWith consent, configure the Herdr pane shell and install selected tool hooks.\nPrint the exact files and changes before each consent question.\nUse the fleet app address for the QR and copyable pairing link.\nOpen the installed Home Screen app to scan or paste the link.\nThe code lasts 10 minutes. Ctrl+C cancels it.\nA temporary app address can be public. Moving it requires pairing again.\nNo phone is required for setup, joins, approvals or daily work.\nThe phone is a full member with a signing key for approval.\nIt holds sealed GitHub, Claude and API-key copies for phone-only joins.\nIt receives no Codex access copies; the keeper supplies those to machines.\nA lost phone needs removal, then guided rotation of the GitHub token, Claude tokens and API keys.\nTemporary address warning: This address will move; you will pair again.\n\n  -h, --help  Show this help.",
  "pdd link": "Usage: pdd link <command>\n\nShow or control this machine's Link service.\n\nCommands: status, restart, stop, logs, devices, revoke, uninstall, reset-identity.\nStopping or restarting Link keeps agents and Herdr running.\nFor fleet membership removal, use pdd fleet remove MEMBER.\n\n  -h, --help  Show this help.",
  "pdd link status": "Usage: pdd link status [--json]\n\nShow Link, relay, Herdr, agents, devices, readiness, keeper/copy age and updates.\n\nOptions:\n  --json  Print the status answer as one JSON line.\n\nShow channel and up to five redacted errors.\nAbsent Link: JSON includes not_running and serviceStatus.\nExit 0 for starting, running or updating; otherwise 1.\n\n  -h, --help  Show this help.",
  "pdd link restart": "Usage: pdd link restart\n\nRestart Link only. Agents and Herdr keep running.\n\nRequire status with a new startedAt within 10 seconds.\nPrint Link restarted, or the true failure and next step.\n\n  -h, --help  Show this help.",
  "pdd link stop": "Usage: pdd link stop\n\nStop Link and remote control on this machine.\n\nAgents and Herdr keep running.\n\n  -h, --help  Show this help.",
  "pdd link logs": "Usage: pdd link logs\n\nPrint the last 200 Link log lines.\n\nLogs contain no tokens, copies or message text.\n\n  -h, --help  Show this help.",
  "pdd link devices": "Usage: pdd link devices\n\nList roster-bound phones and their current access state.\n\nShow id, name, paired time, active or removed state, and push state.\nNever show keys or push endpoints.\n\n  -h, --help  Show this help.",
  "pdd link revoke": "Usage: pdd link revoke ID_OR_NAME\n\nRemove a phone through signed fleet removal and a person check.\n\nThis delegates the same removal as pdd fleet remove MEMBER.\nShow local removal and keeper receipt separately.\nA missing Link never permits a direct device-registry edit.\nAmbiguous names require the full id. Already removed is success.\n\n  -h, --help  Show this help.",
  "pdd link uninstall": "Usage: pdd link uninstall [--forget]\n\nRemove the local Link service and pane-shell integration.\n\nOptions:\n  --forget  Also delete local Link keys and legacy paired-device data.\n\nRestore the saved Herdr shell setting first.\nFleet members must be removed with pdd fleet remove before --forget.\nThis command does not delete keeper sign-ins or agent history.\nHerdr and agents keep running. Retain unfinished run/session runtime folders.\n\n  -h, --help  Show this help.",
  "pdd link reset-identity": "Usage: pdd link reset-identity\n\nGive a cloned installation its own machine key.\n\nLegacy installation: print the new id and pair phones again.\nFleet installation: remove the old member from another machine, then join\nthe clone as a new machine. Never silently replace a fleet member key.\n\n  -h, --help  Show this help.",
  "pdd link run": "Usage: pdd link run\n\nStart the installed Link service entry point.\n\nInternal service command. Not a setup or interactive agent command.\n\n  -h, --help  Show this help.",
  "pdd update": "Usage: pdd update [ACTION] [--fleet] [--force]\n\nShow PDD update state, or request a change.\n\nOptions:\n  --check                 Check the signed release note; install nothing.\n  --now                   Stage and activate at the next safe moment.\n  --to VERSION            Install and pin this exact version.\n  --pin PREFIX            Allow updates only inside this version prefix.\n  --unpin                 Remove the version pin.\n  --rollback              Return to the retained previous good version.\n  --mode auto|ask|never   Set the update mode: Auto, Ask first or Never.\n  --channel stable|beta   Set the normal or optional team test channel.\n  --fleet                 Apply this request to the fleet; default is this machine.\n  --force                 Allow an explicit blocked target with --to or --rollback.\n\nUse at most one ACTION. --channel is an action. --force needs --to or --rollback.\nNo ACTION shows the current, previous, target, mode, channel and pin.\nauto: download in the background and activate at a safe moment.\nask: download and show Update ready; wait for --now or a tap.\nnever: show availability only; an explicit --now can install.\nAll users receive a release after tests. Each machine acts when ready.\nRuns and agents keep their processes and recorded PDD versions.\nA CLI-only change does not restart Link.\nThree failed Link starts in a row restore the previous good version.\nA start with no ready proof within 10 minutes counts as a failed start.\nNo other timer, probation or lost-relay check triggers rollback.\nAutomatic rollback restores the retained previous version without consulting\nminDowngrade. Explicit manual downgrades still obey that floor.\nA failed release is not retried until a different release is published.\nA pin does not bypass a central block or the downgrade floor.\n--force never bypasses a signature, compatibility check or downgrade floor.\nFleet requests show each machine's result; offline machines remain pending.\n\n  -h, --help  Show this help.",
  "pdd doctor": "Usage: pdd doctor [--json | --report | --check-only | --cleanup]\n\nCheck this machine, or review old PDD tools for explicit cleanup.\n\nOptions:\n  --json        Print {ok, checks} as one JSON line.\n  --report      Print a redacted support report to standard output.\n  --check-only  Read local state for a staged-version self-check. No network.\n  --cleanup     Inventory old PDD LaunchAgents, units and pocket helpers.\n                Ask keep, unload or remove for each owned item.\n\nDefault, --json, --report and --check-only change nothing.\n--cleanup is interactive and explicit. Show the exact item and effect first.\nKeep is always available. Never select a service by process name.\nDo not remove live work, native sign-ins or unrelated tool configuration.\nShow PASS, FAIL or SKIP and a repair step for each failed check.\nRun on Alpha alone through the public doctor command.\nOptional client-owned checks are SKIP with a reason when no client is installed.\nInclude PATH, selected tool hooks, service, Herdr, accounts and versions.\nA report includes install phases, account states and expiries, free disk,\nlast good contact and up to 200 redacted log lines.\nNever include tokens, pairing links, message text or private key material.\nReports go to standard output. Exit 0 when there are no FAIL checks; else 1.\nAn unavailable check is SKIP with a reason.\n\n  -h, --help  Show this help.",
  "pdd accounts policy": "Usage: pdd accounts policy [--machine MACHINE] TOOL [--pinned ACCOUNTS --then auto|wait] [--exclude ACCOUNTS]\n\nShow or change this machine/tool Auto selection policy.\n\nOptions:\n  --machine MACHINE  Select a machine (default: this machine).\n  TOOL               codex or claude.\n  --pinned ACCOUNTS  Comma-separated account order; none clears it.\n  --then auto|wait   What follows the pinned list; required with --pinned.\n  --exclude ACCOUNTS Comma-separated accounts to skip; none clears it.\n\nOnly Auto for this machine/tool uses the policy. Fixed accounts stay fixed.\nA policy cannot add another tool or bypass machine account access.\nSelection changes affect the whole machine; each agent moves at step end.\nCross-tool permission is separate and defaults to ask.\n\n  -h, --help  Show this help.",
  "pdd accounts allow": "Usage: pdd accounts allow ACCOUNT --machine MACHINE on|off\n\nAllow or stop future use of an account on a machine.\n\nOptions:\n  --machine MACHINE  Select the machine whose account access changes.\n\nShow the resulting allowed machines.\nTurning access off does not revoke a copied bearer token.\nSelection changes affect the machine/tool; each agent moves at step end.\nShow pending while its current step is active.\n\n  -h, --help  Show this help.",
  "pdd fleet rename": "Usage: pdd fleet rename MACHINE NAME\n\nChange a machine display name in the fleet.\n\nNAME is 1 to 60 characters after trimming.\nThe member key and agent ids stay the same.\n\n  -h, --help  Show this help.",
  "pdd runs-keeper": "Usage: pdd runs-keeper\n\nRun Alpha's local saved-run recovery service.\n\nInstalled at boot or login by pdd setup. Fleet is not required.\nRecover only eligible non-human waits from saved journals and runtimes.\nNever create a second controller, repeat a prompt, or approve a human wait.\n\n  -h, --help  Show this help."
};
for (const route of routes) {
  route.helpText = helpText[`pdd ${route.prefix.join(' ')}`];
  route.groupHelp = helpText[`pdd ${route.prefix[0]}`];
  if (route.id === 'help') route.rootHelp = helpText.pdd;
  const usage=route.helpText?.split('\n')[0];
  if (usage?.startsWith('Usage: ') && route.forms.length===1) route.forms=[form(usage.slice(7),route.forms[0].description)];
}
export const PUBLIC_COMMAND_ROUTES = Object.freeze(routes.map(route => Object.freeze({ ...route,
  prefix: Object.freeze(route.prefix), operands: Object.freeze(route.operands.map(Object.freeze)),
  options: Object.freeze(route.options.map(option=>Object.freeze({...option,...(option.choices?{choices:Object.freeze([...option.choices])}:{})}))), forms: Object.freeze(route.forms) })));
export const PUBLIC_COMMAND_IDS = Object.freeze(PUBLIC_COMMAND_ROUTES.map(route => route.id));
export const PUBLIC_COMMAND_MANIFEST = Object.freeze(PUBLIC_COMMAND_ROUTES.flatMap(route => route.forms));
